<?php
session_start();
if(empty($_SESSION['loggedin'])){header('Location: login.php');exit;}
require_once __DIR__.'/config.php';
require_once __DIR__.'/research_evaluation_helper.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(empty($_SESSION['eval_review_csrf']))$_SESSION['eval_review_csrf']=bin2hex(random_bytes(32));
$csrf=$_SESSION['eval_review_csrf'];$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(400);exit('Invalid request token.');}
 try{
  if(($_POST['action']??'')==='semantic'){
   $run=(int)$_POST['run_id'];$case=(int)$_POST['test_case_id'];$system=$_POST['system_type']==='traditional'?'traditional':'proposed';
   $code=trim((string)$_POST['concept_code']);if($code==='')throw new RuntimeException('Enter a concept code.');
   $expected=(int)$_POST['expected_present'];$found=(int)$_POST['found_present'];
   $q=$pdo->prepare("INSERT INTO evaluation_semantic_annotations(run_id,test_case_id,system_type,concept_code,expected_present,evaluator_found_present,evaluator_id,evaluator_notes) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE expected_present=VALUES(expected_present),evaluator_found_present=VALUES(evaluator_found_present),evaluator_id=VALUES(evaluator_id),evaluator_notes=VALUES(evaluator_notes),reviewed_at=NOW()");
   $q->execute([$run,$case,$system,$code,$expected,$found,(int)($_SESSION['user_id']??0)?:null,trim((string)($_POST['notes']??''))]);
   $notice='Semantic concept review saved.';
  }elseif(($_POST['action']??'')==='survey'){
   $respondent=trim((string)$_POST['respondent_code']);$system=$_POST['system_type']==='traditional'?'traditional':'proposed';$answers=$_POST['rating']??[];
   if($respondent==='')throw new RuntimeException('Use a non-identifying respondent code.');
   $q=$pdo->prepare("INSERT INTO evaluation_survey_responses(respondent_code,system_type,question_id,rating,collected_by) VALUES(?,?,?,?,?)");
   foreach($answers as $qid=>$rating){$rating=(int)$rating;if($rating<1||$rating>5)continue;$q->execute([$respondent,$system,(int)$qid,$rating,(int)($_SESSION['user_id']??0)?:null]);}
   $notice='Survey responses saved.';
  }
 }catch(Throwable $ex){$error=$ex->getMessage();}
}
$runs=$pdo->query("SELECT id,run_name FROM evaluation_runs WHERE status='completed' ORDER BY id DESC")->fetchAll(PDO::FETCH_ASSOC);
$cases=$pdo->query("SELECT c.id,c.case_code,c.billing_description,d.dataset_name FROM evaluation_test_cases c JOIN evaluation_datasets d ON d.id=c.dataset_id ORDER BY c.id DESC LIMIT 500")->fetchAll(PDO::FETCH_ASSOC);
$questions=$pdo->query("SELECT * FROM evaluation_survey_questions WHERE is_active=1 ORDER BY display_order")->fetchAll(PDO::FETCH_ASSOC);
$means=$pdo->query("SELECT system_type,q.dimension,AVG(r.rating) AS weighted_mean,COUNT(*) AS response_count FROM evaluation_survey_responses r JOIN evaluation_survey_questions q ON q.id=r.question_id GROUP BY system_type,q.dimension ORDER BY q.dimension,system_type")->fetchAll(PDO::FETCH_ASSOC);
$annotations=$pdo->query("SELECT system_type,COUNT(*) AS reviewed FROM evaluation_semantic_annotations GROUP BY system_type")->fetchAll(PDO::FETCH_ASSOC);
if(isset($_GET['export'])&&$_GET['export']==='survey'){
 header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="survey_results_'.date('Ymd_His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Respondent Code','System','Question','Dimension','Rating','Date']);$q=$pdo->query("SELECT r.respondent_code,r.system_type,q.question_text,q.dimension,r.rating,r.created_at FROM evaluation_survey_responses r JOIN evaluation_survey_questions q ON q.id=r.question_id ORDER BY r.id");while($row=$q->fetch(PDO::FETCH_NUM))fputcsv($out,$row);fclose($out);exit;
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evaluation Review & Survey</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7f8;color:#172b3a;font:14px Segoe UI,Arial,sans-serif}.wrap{max-width:1100px;margin:auto;padding:24px 16px}h1{font-size:24px}.panel{background:white;border:1px solid #dce5e8;border-radius:12px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}label{font-weight:600}input,select,textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;font:inherit}textarea{min-height:65px}.btn{display:inline-block;padding:10px 14px;background:#0f766e;color:white;border:0;border-radius:7px;text-decoration:none;cursor:pointer}.muted{color:#64748b}.notice{background:#ecfdf5;color:#166534;padding:12px;border-radius:8px}.error{background:#fef2f2;color:#991b1b;padding:12px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e5e7eb}.scroll{overflow:auto}
</style></head><body><main class="wrap"><h1>Semantic Review & Survey Evaluation</h1><p class="muted">Record qualified human review and actual respondent ratings. No sample responses are pre-filled.</p><p><a class="btn" href="research_evaluation.php">Back to Research Evaluation</a> <a class="btn" href="?export=survey">Export survey CSV</a></p>
<?php if($notice):?><p class="notice"><?=h($notice)?></p><?php endif?><?php if($error):?><p class="error"><?=h($error)?></p><?php endif?>
<section class="panel"><h2>1. Human semantic review</h2><p class="muted">Review whether each required meaning concept is communicated, not whether two sentences are identical. Use one annotation per concept per case and system.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="semantic"><div class="grid"><div class="field"><label>Evaluation run</label><select name="run_id" required><?php foreach($runs as $r):?><option value="<?=$r['id']?>">#<?=$r['id']?> — <?=h($r['run_name'])?></option><?php endforeach?></select></div><div class="field"><label>Test case</label><select name="test_case_id" required><?php foreach($cases as $c):?><option value="<?=$c['id']?>"><?=h($c['case_code'].' — '.$c['billing_description'])?></option><?php endforeach?></select></div><div class="field"><label>System output reviewed</label><select name="system_type"><option value="proposed">Proposed system</option><option value="traditional">Traditional baseline</option></select></div><div class="field"><label>Concept code</label><input name="concept_code" required placeholder="e.g. BLOOD_SAMPLE_TEST"></div><div class="field"><label>Should this concept be present?</label><select name="expected_present"><option value="1">Yes</option><option value="0">No</option></select></div><div class="field"><label>Did the explanation communicate it?</label><select name="found_present"><option value="1">Yes</option><option value="0">No</option></select></div></div><div class="field"><label>Evaluator notes</label><textarea name="notes"></textarea></div><button class="btn">Save human review</button></form><p class="muted">The evaluator should be qualified and should use the verified expected meaning. Annotation counts currently recorded: <?php foreach($annotations as $a):?><?=h($a['system_type'])?>: <?=$a['reviewed']?>; <?php endforeach?></p></section>
<section class="panel"><h2>2. Readability, transparency & understanding survey</h2><p class="muted">Use an anonymous respondent code. Collect responses from real participants only. Scale: 5 Strongly Agree, 4 Agree, 3 Neutral, 2 Disagree, 1 Strongly Disagree.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="survey"><div class="grid"><div class="field"><label>Respondent code (no names)</label><input name="respondent_code" required placeholder="R-001"></div><div class="field"><label>Which billing information was evaluated?</label><select name="system_type"><option value="traditional">Traditional baseline</option><option value="proposed">Proposed system</option></select></div></div><?php foreach($questions as $q):?><div class="field"><label><?=h($q['question_text'])?></label><select name="rating[<?=$q['id']?>]" required><option value="">Select rating</option><option value="5">5 — Strongly Agree</option><option value="4">4 — Agree</option><option value="3">3 — Neutral</option><option value="2">2 — Disagree</option><option value="1">1 — Strongly Disagree</option></select></div><?php endforeach?><button class="btn">Save survey response</button></form></section>
<section class="panel"><h2>3. Actual survey weighted means</h2><div class="scroll"><table><thead><tr><th>System</th><th>Dimension</th><th>Weighted mean (1–5)</th><th>Responses</th></tr></thead><tbody><?php foreach($means as $m):?><tr><td><?=h($m['system_type'])?></td><td><?=h($m['dimension'])?></td><td><?=number_format((float)$m['weighted_mean'],2)?></td><td><?=$m['response_count']?></td></tr><?php endforeach?><?php if(!$means):?><tr><td colspan="4" class="muted">No survey responses have been collected.</td></tr><?php endif?></tbody></table></div></section></main></body></html>